-- Catalog-only inventory. No row mutation, no real Supabase connection.
SELECT jsonb_build_object(
 'columns',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'column',a.attname,'notNull',a.attnotnull,'generated',a.attgenerated,'default',pg_get_expr(d.adbin,d.adrelid),'acl',a.attacl::text) ORDER BY n.nspname,c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname IN('public','serien_capability') AND c.relkind='r' AND a.attnum>0 AND NOT a.attisdropped),
 'constraints',(SELECT jsonb_agg(jsonb_build_object('table',conrelid::regclass::text,'name',conname,'type',contype,'definition',pg_get_constraintdef(oid),'validated',convalidated,'deleteAction',confdeltype,'target',CASE WHEN confrelid<>0 THEN confrelid::regclass::text END) ORDER BY conrelid::regclass::text,conname) FROM pg_constraint WHERE connamespace IN('public'::regnamespace,'serien_capability'::regnamespace)),
 'indexes',(SELECT jsonb_agg(to_jsonb(i) ORDER BY schemaname,tablename,indexname) FROM pg_indexes i WHERE schemaname IN('public','serien_capability')),
 'triggers',(SELECT jsonb_agg(jsonb_build_object('table',tgrelid::regclass::text,'name',tgname,'definition',pg_get_triggerdef(oid),'enabled',tgenabled,'internal',tgisinternal) ORDER BY tgrelid::regclass::text,tgname) FROM pg_trigger WHERE tgrelid IN(SELECT c.oid FROM pg_class c WHERE relnamespace IN('public'::regnamespace,'serien_capability'::regnamespace))),
 'functions',(SELECT jsonb_agg(jsonb_build_object('identity',p.oid::regprocedure::text,'owner',r.rolname,'definer',p.prosecdef,'config',p.proconfig,'acl',p.proacl::text,'definition',pg_get_functiondef(p.oid)) ORDER BY p.oid::regprocedure::text) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace JOIN pg_roles r ON r.oid=p.proowner WHERE n.nspname IN('serien_internal','serien_capability')),
 'policies',(SELECT jsonb_agg(to_jsonb(p) ORDER BY schemaname,tablename,policyname) FROM pg_policies p WHERE schemaname IN('public','serien_capability')),
 'tables',(SELECT jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'owner',r.rolname,'rls',c.relrowsecurity,'forceRls',c.relforcerowsecurity,'acl',c.relacl::text,'effectiveAcl',coalesce(c.relacl,acldefault('r',c.relowner))::text) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles r ON r.oid=c.relowner WHERE n.nspname IN('public','serien_capability') AND c.relkind='r'),
 'defaultAcls',(SELECT coalesce(jsonb_agg(jsonb_build_object('creator',defaclrole::regrole::text,'namespace',CASE WHEN defaclnamespace=0 THEN '' ELSE defaclnamespace::regnamespace::text END,'type',defaclobjtype,'acl',defaclacl::text) ORDER BY defaclrole,defaclnamespace,defaclobjtype),'[]') FROM pg_default_acl),
 'authEdges',(SELECT coalesce(jsonb_agg(jsonb_build_object('source',conrelid::regclass::text,'target',confrelid::regclass::text,'name',conname,'definition',pg_get_constraintdef(oid)) ORDER BY conrelid::regclass::text,conname),'[]') FROM pg_constraint WHERE contype='f' AND confrelid='auth.users'::regclass),
 'dependencies',(SELECT coalesce(jsonb_agg(jsonb_build_object('dependent',pg_describe_object(classid,objid,objsubid),'reference',pg_describe_object(refclassid,refobjid,refobjsubid),'kind',deptype) ORDER BY pg_describe_object(classid,objid,objsubid),deptype),'[]') FROM pg_depend WHERE refclassid='pg_class'::regclass AND refobjid IN(SELECT c.oid FROM pg_class c WHERE relnamespace IN('public'::regnamespace,'serien_capability'::regnamespace) OR c.oid='auth.users'::regclass))
);
